import{_ as n,a0 as r,w as p,s as l,ao as u,I as a,x as o,a1 as e,A as s}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const f=JSON.parse('{"title":"如何在 Ubuntu 上用 Yocto 創建你自己的 Linux 發行版 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Ubuntu 上用 Yocto 創建你自己的 Linux 發行版 | LCTT (201703) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Ubuntu 上用 Yocto 創建你自己的 Linux 發行版 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Ubuntu 上用 Yocto 創建你自己的 Linux 發行版 | LCTT (201703) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201703/20170220 How to create your own Linux Distribution with Yocto on Ubuntu","title":"如何在 Ubuntu 上用 Yocto 創建你自己的 Linux 發行版","tag":"201703","desc":""},"relativePath":"201703/20170220 How to create your own Linux Distribution with Yocto on Ubuntu.md","filePath":"[post].md"}'),c={name:"201703/20170220 How to create your own Linux Distribution with Yocto on Ubuntu.md"};function d(g,t,h,w,b,m){const i=r("Link");return p(),l("div",null,[t[13]||(t[13]=u('<h1 id="如何在-ubuntu-上用-yocto-創建你自己的-linux-發行版" tabindex="-1">如何在 Ubuntu 上用 Yocto 創建你自己的 Linux 發行版 <a class="header-anchor" href="#如何在-ubuntu-上用-yocto-創建你自己的-linux-發行版" aria-label="Permalink to “如何在 Ubuntu 上用 Yocto 創建你自己的 Linux 發行版”">​</a></h1><h3 id="本文內容" tabindex="-1">本文內容 <a class="header-anchor" href="#本文內容" aria-label="Permalink to “本文內容”">​</a></h3><p>本文主要聚焦在如何使用 Yocto 在 Ubuntu 上創建一個最小化的 Linux 發行版。Yocto 項目在嵌入式 Linux 的世界非常著名，這是因為它用起來非常靈活、方便。Yocto 的目標是為嵌入式軟硬件開發商創建自己的 Linux 發行版。本文我們將會創建一個可以運行在 QEMU 上的最小化的 Linux，並且在 QEMU 上實際運行。</p><h3 id="開發機的基本條件" tabindex="-1">開發機的基本條件 <a class="header-anchor" href="#開發機的基本條件" aria-label="Permalink to “開發機的基本條件”">​</a></h3><ul><li>最少 4-6 GB 內存</li><li>最新版的 Ubuntu 系統（本文使用了 16.04 LTS）</li><li>磁盤剩餘空間至少 60-80 GB</li><li>在創建 Linux 發行版之前先安裝下面的軟件包</li><li>下載最新的 Yocto（Poky 是其最小開發環境）穩定分支</li></ul><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>apt-get update</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>apt-get install wget git-core unzip make gcc g++ build-essential subversion sed autoconf automake texi2html texinfo coreutils diffstat python-pysqlite2 docbook-utils libsdl1.2-dev libxml-parser-perl libgl1-mesa-dev libglu1-mesa-dev xsltproc desktop-file-utils chrpath groff libtool xterm gawk fop</span></span></code></pre></div><p><img src="https://www.howtoforge.com/images/how-to-create-your-own-linux-distribution-with-yocto/big/1-pre_requisite_packages-1.png" alt="Install prerequisites for Yocto"></p><p>如下所示，開發環境要安裝的軟件包將近 1GB 大小。</p><p><img src="https://www.howtoforge.com/images/how-to-create-your-own-linux-distribution-with-yocto/big/2-pre_requisite_packages-2.png" alt="Install the development packages"></p><p>在這個教程中，系統上克隆的是 poky 的 <code>morty</code> 穩定分支。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span> git clone -b morty git://git.yoctoproject.org/poky.git</span></span></code></pre></div><p><img src="https://www.howtoforge.com/images/how-to-create-your-own-linux-distribution-with-yocto/big/download_morty_of_yocto.png" alt="install poky"></p><p>進入 <code>poky</code> 目錄，然後運行下面的命令為 Yocto 開發環境設置（設置/導出）一些環境變量。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>source oe-init-build-env</span></span></code></pre></div><p>如下所示，在運行了 open embedded (oe) 的構建環境腳本之後，終端裏的路徑會自動切換到 <code>build</code> 目錄，以便進行之後行發行版的的配置和構建。</p><p><img src="https://www.howtoforge.com/images/how-to-create-your-own-linux-distribution-with-yocto/big/source_environment_script.png" alt="Prepare OE build environment"></p><p>上面的截屏展示了在 <code>conf</code> 目錄下創建的文件 <code>local.conf</code>。這是 Yocto 用來設置目標機器細節和 SDK 的目標架構的配置文件。</p><p>如下所示，這裏設置的目標機器是 <code>qemux86-64</code>。</p><p><img src="https://www.howtoforge.com/images/how-to-create-your-own-linux-distribution-with-yocto/big/selected_target.png" alt="Set the target machine type"></p><p>如下面截圖所示，在 <code>local.conf</code> 中取消下面參數的註釋符號。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>DL_DIR ?= &quot;${TOPDIR}/downloads&quot;</span></span></code></pre></div><p><img src="https://www.howtoforge.com/images/how-to-create-your-own-linux-distribution-with-yocto/big/uncheck_Download_parameters.png" alt="Configure local.conf file"></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>SSTATE_DIR ?= &quot;${TOPDIR}/sstate-cache&quot;</span></span></code></pre></div><p><img src="https://www.howtoforge.com/images/how-to-create-your-own-linux-distribution-with-yocto/big/uncheck_sstate_parametes.png" alt="Set SSTATE_DIR"></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>TMPDIR ?= &quot;${TOPDIR}/tmp&quot;</span></span></code></pre></div><p><img src="https://www.howtoforge.com/images/how-to-create-your-own-linux-distribution-with-yocto/big/tempdir_uncheck_paramerter.png" alt="Set TMPDIR"></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>PACKAGE_CLASSES ?= &quot;package_rpm&quot;</span></span>\n<span class="line"><span>SDKMACHINE ?= &quot;i686&quot;</span></span></code></pre></div><p><img src="https://www.howtoforge.com/images/how-to-create-your-own-linux-distribution-with-yocto/big/sdk_and_package_selection.png" alt="Set PACKAGE_CLASSES and SDKMACHINE"></p><p>如下所示，在 <code>local.conf</code> 中為基於 Yocto 的 Linux 設置空密碼和後續的一些參數。否則的話用户就不能登錄進新的發行版。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>EXTRA_IMAGE_FEATURES ?= &quot;debug-tweaks&quot;</span></span></code></pre></div><p><img src="https://www.howtoforge.com/images/how-to-create-your-own-linux-distribution-with-yocto/big/extra-features_for_blank_password.png" alt="Set debug-tweaks option"></p><p>我們並不準備使用任何圖形化工具來創建 Linux OS，比如 <code>toaster</code> （<code>hob</code> 已經不再支持了）。</p><h3 id="yocto-編譯構建過程" tabindex="-1">Yocto 編譯構建過程 <a class="header-anchor" href="#yocto-編譯構建過程" aria-label="Permalink to “Yocto 編譯構建過程”">​</a></h3><p>現在運行下面的 <code>bitbake</code> 工具命令開始為選定的目標機器下載和編譯軟件包。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>bitbake core-image-minimal</span></span></code></pre></div><p><img src="https://www.howtoforge.com/images/how-to-create-your-own-linux-distribution-with-yocto/big/bitbake_coreimageminimal.png" alt="Start bitbake"></p><p><strong>非常重要的是要在普通 Linux 用户下運行上面的命令，而不是使用 root 用户</strong>。如下面截圖所示，當你在 root 用户下運行 bitbake 命令會產生下面所示的錯誤。</p><p><img src="https://www.howtoforge.com/images/how-to-create-your-own-linux-distribution-with-yocto/big/dont_user_as_a_root.png" alt="Do not run bitbake as root"></p><p>再一次運行導出環境變量的腳本（<code>oe-init-build-env</code>），重新執行相同的命令來啓動下載和編譯過程。</p><p><img src="https://www.howtoforge.com/images/how-to-create-your-own-linux-distribution-with-yocto/big/runniing_bitbake_again-normal_user.png" alt="rerun commands"></p><p>如下所示，構建腳本組件的第一步工作是解析配置（<code>recipe</code>）。</p><p><img src="https://www.howtoforge.com/images/how-to-create-your-own-linux-distribution-with-yocto/big/parsing-receipe.png" alt="Parse the build recipes"></p><p>下面的截圖展示了構建腳本的解析過程。同時也顯示了用來構建你的新的基於 yocto 的發行版的構建系統的細節。</p><p><img src="https://www.howtoforge.com/images/how-to-create-your-own-linux-distribution-with-yocto/big/output_of_parsing.png" alt="Building proceeds"></p><p>在下載了 SDK 和必要的庫之後，下一步工作是下載並編譯軟件包。如下截圖展示了為構建新發行版而執行的任務。這一步將會執行 2-3 小時，因為首先要下載需要的軟件包，然後還要為新的 Linux 發行版編譯這些軟件包。</p><p><img src="https://www.howtoforge.com/images/how-to-create-your-own-linux-distribution-with-yocto/big/task_list.png" alt="Compilation will take several hours"></p><p>下面的截圖表明瞭任務列表執行完畢。</p><p><img src="https://www.howtoforge.com/images/how-to-create-your-own-linux-distribution-with-yocto/big/downloaded-all_packages_and_compiled.png" alt=""></p><p>為目標機器類型 <code>qemux86-64</code> 編譯好的新鏡像位於 <code>build/tmp/deploy/images/qemux86-64</code>：</p><p><img src="https://www.howtoforge.com/images/how-to-create-your-own-linux-distribution-with-yocto/big/new_linux_compiled_under_qemux86_64.png" alt="Build complete"></p><p>如下所示，上面的命令如果運行在 <code>Putty</code> 上會產生一個錯誤。</p><p><img src="https://www.howtoforge.com/images/how-to-create-your-own-linux-distribution-with-yocto/big/error_on_putty.png" alt="command error in putty"></p><p>通過 <code>rdp</code> 在 Ubuntu 平台上再次運行上面的命令。</p><p><img src="https://www.howtoforge.com/images/how-to-create-your-own-linux-distribution-with-yocto/big/runqemu_command.png" alt="Command works fine in rdp"></p><p>為運行新的基於 Yocto 的 Linux 發行版的 qemu 打開一個新屏幕。</p><p><img src="https://www.howtoforge.com/images/how-to-create-your-own-linux-distribution-with-yocto/big/new_linux_inside_the_qemu_.png" alt="Open Quemu emulator"></p><p>下面展示了新發行版的登錄界面，同時也顯示了使用的 yocto 項目的版本號。默認的用户名是 <code>root</code> ，密碼為空。</p><p><img src="https://www.howtoforge.com/images/how-to-create-your-own-linux-distribution-with-yocto/big/reference_distro.png" alt="Linux distribution started"></p><p>最後使用 <code>root</code> 用户名和空密碼登錄新發行版。如下截圖所示，在這個最小版本的 Linux 上運行了基本的命令（<code>data</code> 、 <code>ifconfig</code> 和 <code>uname</code>）。</p><p><img src="https://www.howtoforge.com/images/how-to-create-your-own-linux-distribution-with-yocto/big/inside_new_linux_distro_running_on_qemu_3.png" alt="Test the Linux distribution"></p><p>本文的目標是理解使用 Yocto 創建新的 Linux 發行版的過程。</p><hr>',63)),a("p",null,[t[1]||(t[1]=o("via: ",-1)),e(i,{href:"https://www.howtoforge.com/tutorial/how-to-create-your-own-linux-distribution-with-yocto-on-ubuntu/"},{default:s(()=>[...t[0]||(t[0]=[o("https://www.howtoforge.com/tutorial/how-to-create-your-own-linux-distribution-with-yocto-on-ubuntu/",-1)])]),_:1})]),a("p",null,[t[5]||(t[5]=o("作者：",-1)),e(i,{href:"https://www.howtoforge.com/tutorial/how-to-create-your-own-linux-distribution-with-yocto-on-ubuntu/"},{default:s(()=>[...t[2]||(t[2]=[o("Ahmad",-1)])]),_:1}),t[6]||(t[6]=o(" 譯者：",-1)),e(i,{href:"https://github.com/oska874"},{default:s(()=>[...t[3]||(t[3]=[o("Ezio",-1)])]),_:1}),t[7]||(t[7]=o(" 校對：",-1)),e(i,{href:"https://github.com/wxy"},{default:s(()=>[...t[4]||(t[4]=[o("wxy",-1)])]),_:1})]),a("p",null,[t[10]||(t[10]=o("本文由 ",-1)),e(i,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...t[8]||(t[8]=[o("LCTT",-1)])]),_:1}),t[11]||(t[11]=o(" 原創編譯，",-1)),e(i,{href:"https://linux.cn/"},{default:s(()=>[...t[9]||(t[9]=[o("Linux中國",-1)])]),_:1}),t[12]||(t[12]=o(" 榮譽推出",-1))])])}const x=n(c,[["render",d]]);export{f as __pageData,x as default};
